/**
 * Final report = the Perfect Baby Name Report (Rs 3437) or the Complete Baby Name Blueprint (Rs 5957).
 * The Swar tool creates the report row (draft) from the confirmed names; the PDF itself is generated by the
 * existing Perfect / Complete report pages, exactly as before.
 */
import { buildBabyCustomerName, normaliseAlphabet, type BabyNamePreference, type BabyReportFormValues } from "@/lib/baby-reports/perfect-baby-name/form";
import type { PackageTier } from "@/lib/swar/nameFinderPackage";

export interface ReportTarget { table: string; label: string; idPrefix: string; adminPath: string }

export function reportTarget(tier: PackageTier): ReportTarget {
  return tier === "blueprint"
    ? { table: "complete_baby_blueprint_reports", label: "Complete Baby Name Blueprint", idPrefix: "CBB", adminPath: "/admin/reports/complete-baby-blueprint" }
    : { table: "perfect_baby_name_reports", label: "Perfect Baby Name Report", idPrefix: "PBN", adminPath: "/admin/reports/perfect-baby-name" };
}

export function newReportId(tier: PackageTier): string {
  return `${reportTarget(tier).idPrefix}-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`;
}

export interface FinalReportInput {
  name1: string;
  name2: string;            // "" when the customer finalised only one name
  middle: string;
  middleIsFather: boolean;
  surname: string;
  gender: string;           // "boy" | "girl" (the tool's gender) or already "Male" / "Female"
  email: string;
  phone: string;
  dob: string;
  fatherName: string;
  nickName: string;
  preference: BabyNamePreference;
}

const cap = (s: string) => s.trim();
/** "Navishaa" + middle + surname -> "Navishaa Kumar Mishra" (the report's Option field is First + Middle + Last as one string). */
export function fullOption(first: string, middle: string, surname: string): string {
  const f = cap(first);
  return f ? [f, cap(middle), cap(surname)].filter(Boolean).join(" ") : "";
}

export const reportGender = (g: string): string => (/^(girl|female|f)$/i.test(g) ? "Female" : /^(boy|male|m)$/i.test(g) ? "Male" : g);

export function buildReportValues(i: FinalReportInput): BabyReportFormValues {
  const first = cap(i.name1);
  return {
    first_name: first,
    middle_name: cap(i.middle),
    is_middle_name_father_husband: cap(i.middle) ? i.middleIsFather : false,
    last_name: cap(i.surname),
    father_name: cap(i.fatherName),
    gender: reportGender(i.gender),
    email: cap(i.email),
    phone: cap(i.phone),
    dob: i.dob,
    first_alphabet: normaliseAlphabet(first),
    option1_name: fullOption(first, i.middle, i.surname),
    option2_name: i.name2.trim() ? fullOption(i.name2, i.middle, i.surname) : "NA",
    nick_name: cap(i.nickName),
    preference: i.preference,
    status: "draft",
  };
}

/** Same column mapping the Perfect / Complete report pages use when a report is saved. */
export function reportColumns(v: BabyReportFormValues) {
  return {
    customer_name: buildBabyCustomerName(v),
    first_name: v.first_name.trim(),
    middle_name: v.middle_name.trim() || null,
    last_name: v.last_name.trim() || null,
    father_name: v.father_name.trim() || null,
    is_middle_name_father_husband: v.middle_name.trim() ? v.is_middle_name_father_husband : false,
    gender: v.gender,
    email: v.email.trim(),
    phone: v.phone.trim(),
    dob: v.dob,
    first_alphabet: v.first_alphabet,
    option1_name: v.option1_name.trim(),
    option2_name: v.option2_name.trim(),
    nick_name: v.nick_name.trim() || null,
    preference: v.preference,
    status: v.status,
  };
}

export function reportMessage(tier: PackageTier, name: string, pdfUrl: string): string {
  return [
    "Namaskar,",
    "",
    `Your ${reportTarget(tier).label} for *${name}* is ready. You can view and download it here:`,
    pdfUrl,
    "",
    "Please let us know if you have any questions.",
    "",
    "Regards,",
    "Ankshaastra-Empower Your Name",
  ].join("\n");
}
